/**
 * Quote Calculator for Miami Alliance 3PL
 * Calculates storage, handling, pick & pack, and shipping estimates
 * Includes PDF quote generation with company branding
 */

const PRICING = window.MA3PLQuoteEngine
  ? window.MA3PLQuoteEngine.PRICING
  : {
      dimensionalFactor: 139,
      storagePerCubicFtDay: 0.025,
      handlingFee: 3.5,
      pickAndPack: 1.25,
      palletStoragePerDay: 0.75,
      palletHandling: 15.0,
      palletPickPack: 5.0,
      blackWrapping: 7.0,
      storageDays: 30,
      minStorage: 5.0,
      shippingZones: {
        local: 0.45,
        regional: 0.65,
        national: 0.85,
        none: 0,
        dropship: 0,
        localDelivery: 0,
        pickup: 0,
      },
      localDeliveryBase: 120.0,
      localDeliveryPerUnit: 30.0,
      pickupBase: 120.0,
      pickupPerUnit: 30.0,
      dropShipRates: {
        envelope: 1.5,
        small: 3.0,
        medium: 5.0,
        large: 20.0,
      },
      fbaPrep: {
        fnskuLabeling: { rate: 0.3, label: "FNSKU Labeling", unit: "unit" },
        polyBagging: { rate: 0.5, label: "Poly Bagging", unit: "unit" },
        bubbleWrapping: { rate: 1.0, label: "Bubble Wrapping", unit: "unit" },
        bundling: { rate: 2.0, label: "Bundling / Kitting", unit: "bundle" },
        boxLabels: { rate: 3.0, label: "Box Content Labels", unit: "box" },
        inspectionQC: { rate: 0.15, label: "Inspection & QC", unit: "unit" },
      },
    };

const COMPANY_INFO = {
  name: "MIAMI ALLIANCE 3PL",
  address: "8780 NW 100th ST",
  city: "Medley, FL 33178",
  phone: "(786) 873-8819",
  email: "contact@miamialliance3pl.com",
  website: "www.miamialliance3pl.com",
};

// Warehouse-aware company info getter
function getWarehouseCompanyInfo(warehouseId) {
  var WH = window.MA3PLQuoteEngine && window.MA3PLQuoteEngine.WAREHOUSES;
  if (!WH || !WH[warehouseId]) return COMPANY_INFO;
  var wh = WH[warehouseId];
  return {
    name: "MIAMI ALLIANCE 3PL",
    address: wh.address,
    city: wh.city,
    phone: wh.phone,
    email: wh.email,
    website: COMPANY_INFO.website,
    warehouseName: wh.name,
    warehouseShortName: wh.shortName,
  };
}

// Company logo embedded as base64 (300px version for PDF)
const COMPANY_LOGO_BASE64 =
  "data:image/jpeg;base64,";

class QuoteCalculator {
  constructor() {
    // Multi-item cargo support
    this.cargoItems = [
      {
        packageType: "box",
        dimensions: { length: 12, width: 12, height: 12 },
        weight: 25,
        quantity: 1,
        blackWrapping: false,
      },
    ];
    this.activeCargoIndex = 0; // Which item drives the 3D viewer

    // Legacy single-item accessors (backward compat)
    this.packageType = "box";
    this.dimensions = { length: 12, width: 12, height: 12 };
    this.weight = 25;
    this.quantity = 1;
    this.blackWrapping = false;

    this.shippingZone = "none";
    this.storageDays = 30;
    this.dropShipQty = { envelope: 0, small: 0, medium: 0, large: 0 };
    this.selectedWarehouse = "miami";
    this.fbaPrep = {
      enabled: true,
      services: {
        fnskuLabeling: { selected: false, qty: 0 },
        polyBagging: { selected: false, qty: 0 },
        bubbleWrapping: { selected: false, qty: 0 },
        bundling: { selected: false, qty: 0 },
        boxLabels: { selected: false, qty: 0 },
        inspectionQC: { selected: false, qty: 0 },
      },
    };

    this.init();
  }

  init() {
    // Warehouse selector
    const warehouseSelect = document.getElementById("warehouse-select");
    if (warehouseSelect) {
      warehouseSelect.addEventListener("change", (e) => {
        this.selectedWarehouse = e.target.value;
        this.updateZoneLabels();
        this.calculate();
      });
    }

    // Initialize cargo items system
    this.initCargoItems();

    // Add cargo item button
    const addBtn = document.getElementById("add-cargo-item");
    if (addBtn) {
      addBtn.addEventListener("click", () => {
        this.addCargoItem();
      });
    }

    // Shipping zone
    const zoneSelect = document.getElementById("shipping-zone");
    if (zoneSelect) {
      zoneSelect.addEventListener("change", (e) => {
        this.shippingZone = e.target.value;
        // Show/hide drop ship section
        const dropshipGroup = document.getElementById("dropship-group");
        if (dropshipGroup) {
          dropshipGroup.style.display =
            this.shippingZone === "dropship" ? "block" : "none";
          // Reset drop ship quantities when switching away
          if (this.shippingZone !== "dropship") {
            this.dropShipQty = { envelope: 0, small: 0, medium: 0, large: 0 };
            ["envelope", "small", "medium", "large"].forEach((size) => {
              const input = document.getElementById(`dropship-${size}`);
              if (input) input.value = 0;
            });
          }
        }
        // Show/hide flat rate info hint for local delivery & pickup
        this.updateFlatRateHint();
        this.calculate();
      });
    }

    // Drop ship unit quantity controls
    document.querySelectorAll(".dropship-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const box = btn.dataset.box;
        const input = document.getElementById(`dropship-${box}`);
        if (btn.dataset.action === "increase") {
          this.dropShipQty[box] = Math.min(9999, this.dropShipQty[box] + 1);
        } else {
          this.dropShipQty[box] = Math.max(0, this.dropShipQty[box] - 1);
        }
        if (input) input.value = this.dropShipQty[box];
        this.calculate();
      });
    });

    // Drop ship unit quantity inputs
    ["envelope", "small", "medium", "large"].forEach((size) => {
      const input = document.getElementById(`dropship-${size}`);
      if (input) {
        input.addEventListener("input", (e) => {
          this.dropShipQty[size] = Math.max(
            0,
            Math.min(9999, parseInt(e.target.value) || 0),
          );
          this.calculate();
        });
      }
    });

    // Black wrapping is now per-item inside cargo items

    // FBA Prep master toggle
    const fbaPrepEnabled = document.getElementById("fba-prep-enabled");
    if (fbaPrepEnabled) {
      fbaPrepEnabled.addEventListener("change", (e) => {
        this.fbaPrep.enabled = e.target.checked;
        const servicesGrid = document.getElementById("fba-prep-services");
        if (servicesGrid) {
          servicesGrid.style.display = this.fbaPrep.enabled ? "grid" : "none";
        }
        // Reset all services when disabling
        if (!this.fbaPrep.enabled) {
          Object.keys(this.fbaPrep.services).forEach((key) => {
            this.fbaPrep.services[key] = { selected: false, qty: 0 };
          });
          document.querySelectorAll(".fba-svc-check").forEach((cb) => {
            cb.checked = false;
          });
          document.querySelectorAll(".fba-qty-input").forEach((inp) => {
            inp.value = 0;
          });
          document.querySelectorAll(".fba-svc-qty").forEach((el) => {
            el.style.display = "none";
          });
          document.querySelectorAll(".fba-prep-item").forEach((el) => {
            el.classList.remove("active");
          });
        }
        this.calculate();
      });
    }

    // FBA Prep individual service checkboxes
    document.querySelectorAll(".fba-svc-check").forEach((checkbox) => {
      checkbox.addEventListener("change", (e) => {
        const serviceKey = e.target.dataset.service;
        this.fbaPrep.services[serviceKey].selected = e.target.checked;
        const item = e.target.closest(".fba-prep-item");
        const qtyDiv = item ? item.querySelector(".fba-svc-qty") : null;
        if (qtyDiv) {
          qtyDiv.style.display = e.target.checked ? "flex" : "none";
        }
        if (item) {
          item.classList.toggle("active", e.target.checked);
        }
        // Auto-set qty to 1 when first checked
        if (e.target.checked && this.fbaPrep.services[serviceKey].qty === 0) {
          this.fbaPrep.services[serviceKey].qty = 1;
          const qtyInput = item ? item.querySelector(".fba-qty-input") : null;
          if (qtyInput) qtyInput.value = 1;
        }
        if (!e.target.checked) {
          this.fbaPrep.services[serviceKey].qty = 0;
          const qtyInput = item ? item.querySelector(".fba-qty-input") : null;
          if (qtyInput) qtyInput.value = 0;
        }
        this.calculate();
      });
    });

    // FBA Prep quantity buttons
    document.querySelectorAll(".fba-qty-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const serviceKey = btn.dataset.service;
        const item = btn.closest(".fba-prep-item");
        const input = item ? item.querySelector(".fba-qty-input") : null;
        if (btn.dataset.action === "increase") {
          this.fbaPrep.services[serviceKey].qty = Math.min(
            99999,
            this.fbaPrep.services[serviceKey].qty + 1,
          );
        } else {
          this.fbaPrep.services[serviceKey].qty = Math.max(
            0,
            this.fbaPrep.services[serviceKey].qty - 1,
          );
        }
        if (input) input.value = this.fbaPrep.services[serviceKey].qty;
        this.calculate();
      });
    });

    // FBA Prep quantity inputs
    document.querySelectorAll(".fba-qty-input").forEach((input) => {
      input.addEventListener("input", (e) => {
        const serviceKey = e.target.dataset.service;
        this.fbaPrep.services[serviceKey].qty = Math.max(
          0,
          Math.min(99999, parseInt(e.target.value) || 0),
        );
        this.calculate();
      });
    });

    this.applyPrefillFromQuery();

    // Initial calculation
    this.calculate();
  }

  applyPrefillFromQuery() {
    const params = new URLSearchParams(window.location.search);
    const service = (params.get("service") || "").trim().toLowerCase();
    const warehouse = (params.get("warehouse") || "").trim().toLowerCase();

    const warehouseSelect = document.getElementById("warehouse-select");
    if (
      warehouse &&
      warehouseSelect &&
      window.MA3PLQuoteEngine &&
      window.MA3PLQuoteEngine.WAREHOUSES &&
      window.MA3PLQuoteEngine.WAREHOUSES[warehouse]
    ) {
      warehouseSelect.value = warehouse;
      warehouseSelect.dispatchEvent(new Event("change", { bubbles: true }));
    }

    if (!service) return;

    if (["fba", "fba-prep", "amazon", "amazon-fba"].includes(service)) {
      const fbaToggle = document.getElementById("fba-prep-enabled");
      if (fbaToggle && !fbaToggle.checked) {
        fbaToggle.checked = true;
        fbaToggle.dispatchEvent(new Event("change", { bubbles: true }));
      }
      return;
    }

    const zoneSelect = document.getElementById("shipping-zone");
    if (!zoneSelect) return;

    const zoneByService = {
      dropship: "dropship",
      "drop-ship": "dropship",
      dropshipping: "dropship",
      pickup: "pickup",
      "local-delivery": "localDelivery",
    };
    const nextZone = zoneByService[service];
    if (nextZone && zoneSelect.value !== nextZone) {
      zoneSelect.value = nextZone;
      zoneSelect.dispatchEvent(new Event("change", { bubbles: true }));
    }
  }

  // ===== Cargo Items System =====

  initCargoItems() {
    const list = document.getElementById("cargo-items-list");
    if (!list) return;
    const items = list.querySelectorAll(".cargo-item");
    items.forEach((itemEl, idx) => {
      this.bindCargoItemEvents(itemEl, idx);
    });
    this.updateRemoveButtons();
  }

  addCargoItem() {
    const list = document.getElementById("cargo-items-list");
    if (!list) return;
    const newIndex = this.cargoItems.length;
    const newItem = {
      packageType: "box",
      dimensions: { length: 12, width: 12, height: 12 },
      weight: 25,
      quantity: 1,
      blackWrapping: false,
    };
    this.cargoItems.push(newItem);

    // Create new cargo item DOM
    const div = document.createElement("div");
    div.className = "cargo-item";
    div.dataset.index = newIndex;
    div.innerHTML = `
      <div class="cargo-item-header">
        <span class="cargo-item-number">Item #${newIndex + 1}</span>
        <button type="button" class="cargo-item-remove" title="Remove item">✕</button>
      </div>
      <div class="cargo-item-type">
        <button type="button" class="package-option active" data-type="box">
          <span class="package-icon">📦</span>
          <span class="package-name">Box</span>
        </button>
        <button type="button" class="package-option" data-type="pallet">
          <span class="package-icon">🏗️</span>
          <span class="package-name">Pallet</span>
        </button>
      </div>
      <div class="cargo-item-details">
        <div class="cargo-dim-row">
          <div class="cargo-dim-group">
            <input type="number" class="cargo-dim-input" data-dim="length" value="12" min="1" max="120" placeholder="L">
            <span class="cargo-dim-label">L</span>
          </div>
          <span class="cargo-dim-x">×</span>
          <div class="cargo-dim-group">
            <input type="number" class="cargo-dim-input" data-dim="width" value="12" min="1" max="120" placeholder="W">
            <span class="cargo-dim-label">W</span>
          </div>
          <span class="cargo-dim-x">×</span>
          <div class="cargo-dim-group">
            <input type="number" class="cargo-dim-input" data-dim="height" value="12" min="1" max="120" placeholder="H">
            <span class="cargo-dim-label">H</span>
          </div>
          <span class="cargo-dim-unit">in</span>
        </div>
        <div class="cargo-weight-qty-row">
          <div class="cargo-weight-group">
            <input type="number" class="cargo-weight-input" value="25" min="1" max="2000" placeholder="Weight">
            <span class="cargo-dim-label">lbs</span>
          </div>
          <div class="cargo-qty-group">
            <button type="button" class="qty-btn cargo-qty-dec">−</button>
            <input type="number" class="cargo-qty-input" value="1" min="1" max="1000">
            <button type="button" class="qty-btn cargo-qty-inc">+</button>
          </div>
        </div>
        <div class="cargo-wrapping-row" style="display:none;">
          <label style="display:flex;align-items:center;gap:6px;cursor:pointer;font-size:0.85rem;">
            <input type="checkbox" class="cargo-wrapping-check">
            <span>Black Wrapping (+$7/pallet)</span>
          </label>
        </div>
      </div>
    `;
    list.appendChild(div);
    this.bindCargoItemEvents(div, newIndex);
    this.updateRemoveButtons();
    this.calculate();
  }

  removeCargoItem(index) {
    if (this.cargoItems.length <= 1) return;
    this.cargoItems.splice(index, 1);

    // Rebuild DOM indices
    const list = document.getElementById("cargo-items-list");
    if (!list) return;
    const items = list.querySelectorAll(".cargo-item");
    const itemToRemove = Array.from(items).find(
      (el) => parseInt(el.dataset.index) === index,
    );
    if (itemToRemove) itemToRemove.remove();

    // Re-index remaining items
    const remaining = list.querySelectorAll(".cargo-item");
    remaining.forEach((el, idx) => {
      el.dataset.index = idx;
      const numSpan = el.querySelector(".cargo-item-number");
      if (numSpan) numSpan.textContent = `Item #${idx + 1}`;
    });

    if (this.activeCargoIndex >= this.cargoItems.length) {
      this.activeCargoIndex = this.cargoItems.length - 1;
    }
    this.syncLegacyState();
    this.updateRemoveButtons();
    this.calculate();
  }

  updateRemoveButtons() {
    const list = document.getElementById("cargo-items-list");
    if (!list) return;
    const items = list.querySelectorAll(".cargo-item");
    items.forEach((el) => {
      const btn = el.querySelector(".cargo-item-remove");
      if (btn) {
        btn.style.display = items.length > 1 ? "flex" : "none";
      }
    });
  }

  bindCargoItemEvents(itemEl, index) {
    const self = this;

    // Package type toggle
    const typeBtns = itemEl.querySelectorAll(
      ".cargo-item-type .package-option",
    );
    typeBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        const idx = parseInt(itemEl.dataset.index);
        typeBtns.forEach((b) => b.classList.remove("active"));
        btn.classList.add("active");
        self.cargoItems[idx].packageType = btn.dataset.type;

        // Set defaults for type
        if (btn.dataset.type === "pallet") {
          self.cargoItems[idx].dimensions = {
            length: 48,
            width: 40,
            height: 48,
          };
          self.cargoItems[idx].weight = 500;
          const dims = itemEl.querySelectorAll(".cargo-dim-input");
          dims.forEach((d) => {
            if (d.dataset.dim === "length") d.value = 48;
            if (d.dataset.dim === "width") d.value = 40;
            if (d.dataset.dim === "height") d.value = 48;
          });
          const wInput = itemEl.querySelector(".cargo-weight-input");
          if (wInput) wInput.value = 500;
        } else {
          self.cargoItems[idx].dimensions = {
            length: 12,
            width: 12,
            height: 12,
          };
          self.cargoItems[idx].weight = 25;
          const dims = itemEl.querySelectorAll(".cargo-dim-input");
          dims.forEach((d) => {
            if (d.dataset.dim === "length") d.value = 12;
            if (d.dataset.dim === "width") d.value = 12;
            if (d.dataset.dim === "height") d.value = 12;
          });
          const wInput = itemEl.querySelector(".cargo-weight-input");
          if (wInput) wInput.value = 25;
          // Reset wrapping when switching from pallet
          self.cargoItems[idx].blackWrapping = false;
          const wrapCheck = itemEl.querySelector(".cargo-wrapping-check");
          if (wrapCheck) wrapCheck.checked = false;
        }

        // Show/hide wrapping row
        const wrapRow = itemEl.querySelector(".cargo-wrapping-row");
        if (wrapRow) {
          wrapRow.style.display =
            btn.dataset.type === "pallet" ? "block" : "none";
        }

        self.activeCargoIndex = idx;
        self.syncLegacyState();
        self.calculate();

        // 3D viewer
        if (window.quote3D) {
          window.quote3D.setPackageType(self.cargoItems[idx].packageType);
          window.quote3D.updateDimensions(
            self.cargoItems[idx].dimensions.length,
            self.cargoItems[idx].dimensions.width,
            self.cargoItems[idx].dimensions.height,
          );
        }
      });
    });

    // Dimension inputs
    itemEl.querySelectorAll(".cargo-dim-input").forEach((input) => {
      input.addEventListener("input", (e) => {
        const idx = parseInt(itemEl.dataset.index);
        const dim = e.target.dataset.dim;
        const value = Math.max(1, Math.min(120, parseInt(e.target.value) || 1));
        self.cargoItems[idx].dimensions[dim] = value;
        self.activeCargoIndex = idx;
        self.syncLegacyState();
        self.calculate();

        if (window.quote3D) {
          window.quote3D.updateDimensions(
            self.cargoItems[idx].dimensions.length,
            self.cargoItems[idx].dimensions.width,
            self.cargoItems[idx].dimensions.height,
          );
        }
      });
    });

    // Weight input
    const weightInput = itemEl.querySelector(".cargo-weight-input");
    if (weightInput) {
      weightInput.addEventListener("input", (e) => {
        const idx = parseInt(itemEl.dataset.index);
        self.cargoItems[idx].weight = Math.max(
          1,
          Math.min(2000, parseInt(e.target.value) || 1),
        );
        self.activeCargoIndex = idx;
        self.syncLegacyState();
        self.calculate();
      });
    }

    // Quantity controls
    const qtyDec = itemEl.querySelector(".cargo-qty-dec");
    const qtyInc = itemEl.querySelector(".cargo-qty-inc");
    const qtyInput = itemEl.querySelector(".cargo-qty-input");

    if (qtyDec) {
      qtyDec.addEventListener("click", (e) => {
        e.preventDefault();
        const idx = parseInt(itemEl.dataset.index);
        self.cargoItems[idx].quantity = Math.max(
          1,
          self.cargoItems[idx].quantity - 1,
        );
        if (qtyInput) qtyInput.value = self.cargoItems[idx].quantity;
        self.syncLegacyState();
        self.calculate();
      });
    }
    if (qtyInc) {
      qtyInc.addEventListener("click", (e) => {
        e.preventDefault();
        const idx = parseInt(itemEl.dataset.index);
        self.cargoItems[idx].quantity = Math.min(
          1000,
          self.cargoItems[idx].quantity + 1,
        );
        if (qtyInput) qtyInput.value = self.cargoItems[idx].quantity;
        self.syncLegacyState();
        self.calculate();
      });
    }
    if (qtyInput) {
      qtyInput.addEventListener("input", (e) => {
        const idx = parseInt(itemEl.dataset.index);
        self.cargoItems[idx].quantity = Math.max(
          1,
          Math.min(1000, parseInt(e.target.value) || 1),
        );
        self.syncLegacyState();
        self.calculate();
      });
    }

    // Black wrapping checkbox
    const wrapCheck = itemEl.querySelector(".cargo-wrapping-check");
    if (wrapCheck) {
      wrapCheck.addEventListener("change", (e) => {
        const idx = parseInt(itemEl.dataset.index);
        self.cargoItems[idx].blackWrapping = e.target.checked;
        self.syncLegacyState();
        self.calculate();
      });
    }

    // Remove button
    const removeBtn = itemEl.querySelector(".cargo-item-remove");
    if (removeBtn) {
      removeBtn.addEventListener("click", () => {
        const idx = parseInt(itemEl.dataset.index);
        self.removeCargoItem(idx);
      });
    }
  }

  syncLegacyState() {
    // Keep legacy single-item state in sync with active cargo item
    const active = this.cargoItems[this.activeCargoIndex] || this.cargoItems[0];
    if (active) {
      this.packageType = active.packageType;
      this.dimensions = { ...active.dimensions };
      this.weight = active.weight;
      this.quantity = active.quantity;
      this.blackWrapping = active.blackWrapping;
    }
  }

  setDimensions(length, width, height) {
    this.dimensions = { length, width, height };
  }

  getCubicFeet() {
    if (window.MA3PLQuoteEngine) {
      return window.MA3PLQuoteEngine.getCubicFeet(this.dimensions);
    }
    const { length, width, height } = this.dimensions;
    return (length * width * height) / 1728;
  }

  getDimensionalWeight() {
    if (window.MA3PLQuoteEngine) {
      return window.MA3PLQuoteEngine.getDimensionalWeight(this.dimensions);
    }
    const { length, width, height } = this.dimensions;
    return (length * width * height) / PRICING.dimensionalFactor;
  }

  getBillableWeight() {
    if (window.MA3PLQuoteEngine) {
      return window.MA3PLQuoteEngine.getBillableWeight(
        this.weight,
        this.dimensions,
      );
    }
    return Math.max(this.weight, this.getDimensionalWeight());
  }

  calculate() {
    // Build multi-item input
    const items = this.cargoItems.map((item) => ({
      packageType: item.packageType,
      dimensions: item.dimensions,
      weight: item.weight,
      quantity: item.quantity,
      blackWrapping: item.blackWrapping,
    }));
    const sharedOptions = {
      shippingZone: this.shippingZone,
      storageDays: this.storageDays,
      dropShipQty: this.dropShipQty,
      fbaPrep: this.fbaPrep,
    };

    let multiResult = null;
    let result = null;

    if (
      window.MA3PLQuoteEngine &&
      window.MA3PLQuoteEngine.calculateMultiEstimate
    ) {
      multiResult = window.MA3PLQuoteEngine.calculateMultiEstimate(
        items,
        sharedOptions,
      );
      result = multiResult.totals;
      // Use active item for dim/cubic display
      const activeItemResult =
        multiResult.items[this.activeCargoIndex] || multiResult.items[0];
      result.dimWeight = activeItemResult.dimWeight;
      result.cubicFt = activeItemResult.cubicFt;
      result.billableWeight = activeItemResult.billableWeight;
    } else if (window.MA3PLQuoteEngine) {
      // Fallback: single item via old method
      const singleResult = window.MA3PLQuoteEngine.calculateEstimate({
        packageType: this.packageType,
        dimensions: this.dimensions,
        weight: this.weight,
        quantity: this.quantity,
        shippingZone: this.shippingZone,
        storageDays: this.storageDays,
        blackWrapping: this.blackWrapping,
        dropShipQty: this.dropShipQty,
        fbaPrep: this.fbaPrep,
      });
      result = singleResult;
    } else {
      // Inline fallback for single item
      const cubicFt = this.getCubicFeet();
      const dimWeight = this.getDimensionalWeight();
      const billableWeight = this.getBillableWeight();
      let storage = 0,
        handling = 0,
        pickPack = 0,
        shipping = 0,
        wrapping = 0,
        dropship = 0;

      if (this.packageType === "pallet") {
        storage =
          PRICING.palletStoragePerDay * this.storageDays * this.quantity;
        handling = PRICING.palletHandling * this.quantity;
        pickPack = PRICING.palletPickPack * this.quantity;
        if (this.shippingZone === "dropship") {
          dropship = this.calculateDropShipTotal();
        } else if (this.shippingZone === "localDelivery") {
          shipping =
            (PRICING.localDeliveryBase || 120) +
            Math.max(0, this.quantity - 1) *
              (PRICING.localDeliveryPerUnit || 30);
        } else if (this.shippingZone === "pickup") {
          shipping =
            (PRICING.pickupBase || 120) +
            Math.max(0, this.quantity - 1) * (PRICING.pickupPerUnit || 30);
        } else if (this.shippingZone !== "none") {
          shipping =
            billableWeight *
            PRICING.shippingZones[this.shippingZone] *
            this.quantity;
        }
        if (this.blackWrapping) {
          wrapping = PRICING.blackWrapping * this.quantity;
        }
      } else {
        storage =
          cubicFt *
          PRICING.storagePerCubicFtDay *
          this.storageDays *
          this.quantity;
        handling = PRICING.handlingFee * this.quantity;
        pickPack = PRICING.pickAndPack * this.quantity;
        if (this.shippingZone === "dropship") {
          dropship = this.calculateDropShipTotal();
        } else if (this.shippingZone === "localDelivery") {
          shipping =
            (PRICING.localDeliveryBase || 120) +
            Math.max(0, this.quantity - 1) *
              (PRICING.localDeliveryPerUnit || 30);
        } else if (this.shippingZone === "pickup") {
          shipping =
            (PRICING.pickupBase || 120) +
            Math.max(0, this.quantity - 1) * (PRICING.pickupPerUnit || 30);
        } else if (this.shippingZone !== "none") {
          shipping =
            billableWeight *
            PRICING.shippingZones[this.shippingZone] *
            this.quantity;
        }
      }

      storage = Math.max(storage, PRICING.minStorage || 5.0);
      let fbaPrepTotal = 0;
      if (this.fbaPrep && this.fbaPrep.enabled && PRICING.fbaPrep) {
        Object.keys(this.fbaPrep.services).forEach((key) => {
          const svc = this.fbaPrep.services[key];
          if (svc && svc.selected && svc.qty > 0 && PRICING.fbaPrep[key]) {
            fbaPrepTotal += svc.qty * PRICING.fbaPrep[key].rate;
          }
        });
      }
      const total =
        storage +
        handling +
        pickPack +
        shipping +
        wrapping +
        dropship +
        fbaPrepTotal;
      result = {
        cubicFt,
        dimWeight,
        billableWeight,
        storage,
        handling,
        pickPack,
        shipping,
        wrapping,
        dropship,
        fbaPrepTotal,
        total,
      };
    }

    // Store multiResult for PDF generation
    this._lastMultiResult = multiResult;

    // Update UI
    this.updateDisplay({
      dimWeight: (result.dimWeight || 0).toFixed
        ? result.dimWeight.toFixed(1)
        : "0.0",
      cubicFt: (result.cubicFt || 0).toFixed
        ? result.cubicFt.toFixed(1)
        : "0.0",
      storage: result.storage,
      handling: result.handling,
      pickPack: result.pickPack,
      shipping: result.shipping,
      wrapping: result.wrapping || 0,
      dropship: result.dropship,
      fbaPrepTotal: result.fbaPrepTotal || 0,
      total: result.total,
    });

    // Render per-item breakdown
    this.renderCargoBreakdown(multiResult);

    // Track quote calculation (debounced)
    if (window.MA3PLAnalytics && !this._calcDebounce) {
      this._calcDebounce = setTimeout(() => {
        const activeItem =
          this.cargoItems[this.activeCargoIndex] || this.cargoItems[0];
        MA3PLAnalytics.trackQuoteCalculation(
          activeItem.packageType,
          `${activeItem.dimensions.length}x${activeItem.dimensions.width}x${activeItem.dimensions.height}`,
          activeItem.quantity,
          result.total,
        );
        this._calcDebounce = null;
      }, 2000);
    }

    return {
      storage: result.storage,
      handling: result.handling,
      pickPack: result.pickPack,
      shipping: result.shipping,
      wrapping: result.wrapping || 0,
      dropship: result.dropship,
      fbaPrepTotal: result.fbaPrepTotal || 0,
      total: result.total,
    };
  }

  updateDisplay(values) {
    const elements = {
      "result-dim-weight": `${values.dimWeight} lbs`,
      "result-cubic-ft": `${values.cubicFt} ft³`,
      "result-storage": this.formatCurrency(values.storage),
      "result-handling": this.formatCurrency(values.handling),
      "result-pickpack": this.formatCurrency(values.pickPack),
      "result-shipping": this.formatCurrency(values.shipping),
      "result-wrapping": this.formatCurrency(values.wrapping),
      "result-dropship": this.formatCurrency(values.dropship),
      "result-fba-prep": this.formatCurrency(values.fbaPrepTotal || 0),
      "result-total": this.formatCurrency(values.total),
    };

    for (const [id, value] of Object.entries(elements)) {
      const el = document.getElementById(id);
      if (el) el.textContent = value;
    }

    // Show/hide wrapping row - show if any cargo item has wrapping
    const wrappingRow = document.getElementById("wrapping-row");
    if (wrappingRow) {
      const anyWrapping = this.cargoItems.some(
        (item) => item.packageType === "pallet" && item.blackWrapping,
      );
      wrappingRow.style.display = anyWrapping ? "flex" : "none";
    }

    // Show/hide drop ship row
    const dropshipRow = document.getElementById("dropship-row");
    if (dropshipRow) {
      dropshipRow.style.display =
        this.shippingZone === "dropship" && values.dropship > 0
          ? "flex"
          : "none";
    }

    // Show/hide FBA prep row
    const fbaPrepRow = document.getElementById("fba-prep-row");
    if (fbaPrepRow) {
      fbaPrepRow.style.display =
        this.fbaPrep.enabled && (values.fbaPrepTotal || 0) > 0
          ? "flex"
          : "none";
    }

    // Render FBA prep per-service breakdown
    this.renderFbaPrepBreakdown();

    // Show/hide shipping row (hide when no shipping or dropship)
    const shippingEl = document.getElementById("result-shipping");
    if (shippingEl && shippingEl.parentElement) {
      shippingEl.parentElement.style.display =
        this.shippingZone === "none" || this.shippingZone === "dropship"
          ? "none"
          : "flex";
    }
  }

  renderCargoBreakdown(multiResult) {
    const container = document.getElementById("cargo-items-breakdown");
    if (!container) return;

    // Only show breakdown if multiple items
    if (!multiResult || multiResult.items.length <= 1) {
      container.innerHTML = "";
      return;
    }

    let html = "";
    multiResult.items.forEach((itemResult, idx) => {
      const item = this.cargoItems[idx];
      if (!item) return;
      const typeLabel = item.packageType === "pallet" ? "Pallet" : "Box";
      const dims = `${item.dimensions.length}×${item.dimensions.width}×${item.dimensions.height}"`;
      const itemTotal =
        itemResult.storage +
        itemResult.handling +
        itemResult.pickPack +
        itemResult.shipping +
        itemResult.wrapping;
      html += `<div class="cargo-item-subtotal">
        <div class="cargo-item-subtotal-header">
          <span>Item #${idx + 1}: ${typeLabel} ${dims} × ${item.quantity}</span>
          <span>${this.formatCurrency(itemTotal)}</span>
        </div>
        <div class="cargo-item-subtotal-details">
          ${item.weight}lbs · Storage ${this.formatCurrency(itemResult.storage)} · Handling ${this.formatCurrency(itemResult.handling)} · P&P ${this.formatCurrency(itemResult.pickPack)}${itemResult.shipping > 0 ? " · Ship " + this.formatCurrency(itemResult.shipping) : ""}${itemResult.wrapping > 0 ? " · Wrap " + this.formatCurrency(itemResult.wrapping) : ""}
        </div>
      </div>`;
    });
    container.innerHTML = html;
  }

  renderFbaPrepBreakdown() {
    const container = document.getElementById("fba-prep-breakdown");
    if (!container) return;

    if (!this.fbaPrep || !this.fbaPrep.enabled) {
      container.innerHTML = "";
      return;
    }

    const breakdown = this.getFbaPrepBreakdown();
    if (breakdown.length === 0) {
      container.innerHTML = "";
      return;
    }

    let html = "";
    breakdown.forEach((item) => {
      html +=
        '<div class="quote-line fba-breakdown-line">' +
        '<span class="fba-breakdown-label">' +
        item.label +
        " x" +
        item.qty +
        " @ $" +
        item.rate.toFixed(2) +
        "/" +
        item.unit +
        "</span>" +
        "<span>" +
        this.formatCurrency(item.total) +
        "</span>" +
        "</div>";
    });
    container.innerHTML = html;
  }

  calculateDropShipTotal() {
    let total = 0;
    for (const [size, qty] of Object.entries(this.dropShipQty)) {
      total += qty * PRICING.dropShipRates[size];
    }
    return total;
  }

  getDropShipBreakdown() {
    const lines = [];
    const labels = {
      envelope: "Envelopes",
      small: "Small Box",
      medium: "Medium Box",
      large: "Large Box",
    };
    for (const [size, qty] of Object.entries(this.dropShipQty)) {
      if (qty > 0) {
        lines.push({
          label: labels[size],
          qty: qty,
          rate: PRICING.dropShipRates[size],
          total: qty * PRICING.dropShipRates[size],
        });
      }
    }
    return lines;
  }

  getFbaPrepBreakdown() {
    const lines = [];
    if (!this.fbaPrep || !this.fbaPrep.enabled) return lines;
    const fbaRates = PRICING.fbaPrep || {};
    for (const [key, svc] of Object.entries(this.fbaPrep.services)) {
      if (svc.selected && svc.qty > 0 && fbaRates[key]) {
        lines.push({
          label: fbaRates[key].label,
          qty: svc.qty,
          rate: fbaRates[key].rate,
          unit: fbaRates[key].unit,
          total: svc.qty * fbaRates[key].rate,
        });
      }
    }
    return lines;
  }

  formatCurrency(amount) {
    return "$" + amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  }

  generateQuoteNumber() {
    const date = new Date();
    const dateStr = date.toISOString().slice(0, 10).replace(/-/g, "");
    const random = Math.floor(Math.random() * 10000)
      .toString()
      .padStart(4, "0");
    return `MA3PL-${dateStr}-${random}`;
  }

  updateFlatRateHint() {
    let hint = document.getElementById("flat-rate-hint");
    if (!hint) {
      // Create the hint element if it doesn't exist
      const zoneSelect = document.getElementById("shipping-zone");
      if (zoneSelect && zoneSelect.parentElement) {
        hint = document.createElement("div");
        hint.id = "flat-rate-hint";
        hint.style.cssText =
          "margin-top:6px;padding:8px 12px;background:#f0f9ff;border-left:3px solid #1e3a5f;border-radius:4px;font-size:0.85rem;color:#1e3a5f;display:none;";
        zoneSelect.parentElement.appendChild(hint);
      }
    }
    if (!hint) return;
    const P = window.MA3PLQuoteEngine
      ? window.MA3PLQuoteEngine.PRICING
      : PRICING;
    if (
      this.shippingZone === "localDelivery" ||
      this.shippingZone === "pickup"
    ) {
      const base = P.localDeliveryBase || P.pickupBase || 120;
      const perUnit = P.localDeliveryPerUnit || P.pickupPerUnit || 30;
      hint.innerHTML = `<strong>Our Truck Rate:</strong> $${base.toFixed(2)} base (1st pallet) + $${perUnit.toFixed(2)} per additional pallet`;
      hint.style.display = "block";
    } else {
      hint.style.display = "none";
    }
  }

  getZoneName(zone) {
    const WH = window.MA3PLQuoteEngine && window.MA3PLQuoteEngine.WAREHOUSES;
    const wh = WH && WH[this.selectedWarehouse];
    const names = {
      local: wh ? wh.localZoneLabel : "Local (Florida)",
      regional: wh ? wh.regionalZoneLabel : "Regional (Southeast)",
      national: "National",
      none: "No Shipping Required",
      dropship: "Drop Ship (by unit)",
      localDelivery: "Local Delivery (Our Truck)",
      pickup: "Warehouse Pick Up (Our Truck)",
    };
    return names[zone] || zone;
  }

  updateZoneLabels() {
    const zoneSelect = document.getElementById("shipping-zone");
    if (!zoneSelect) return;
    const WH = window.MA3PLQuoteEngine && window.MA3PLQuoteEngine.WAREHOUSES;
    const wh = WH && WH[this.selectedWarehouse];
    if (!wh) return;
    const localOpt = zoneSelect.querySelector('option[value="local"]');
    const regionalOpt = zoneSelect.querySelector('option[value="regional"]');
    if (localOpt) localOpt.textContent = wh.localZoneLabel;
    if (regionalOpt) regionalOpt.textContent = wh.regionalZoneLabel;
  }

  generatePDF() {
    // Check if jsPDF is loaded
    if (typeof window.jspdf === "undefined") {
      alert("PDF library loading... Please try again in a moment.");
      return;
    }

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();

    const quoteNumber = this.generateQuoteNumber();
    const currentDate = new Date().toLocaleDateString("en-US", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });

    // Colors
    const primaryColor = [30, 58, 95]; // #1e3a5f
    const accentColor = [20, 184, 166]; // #14b8a6
    const grayColor = [100, 116, 139]; // #64748b
    const lightGray = [241, 245, 249]; // #f1f5f9
    const darkNavy = [15, 23, 42]; // #0f172a

    // Calculate values
    const cubicFt = this.getCubicFeet();
    const dimWeight = this.getDimensionalWeight();
    const billableWeight = this.getBillableWeight();
    const results = this.calculate();
    const multiResult = this._lastMultiResult;
    const pageHeight = doc.internal.pageSize.getHeight();
    const pageStartY = 20;
    const pdfWarehouseInfo = getWarehouseCompanyInfo(this.selectedWarehouse);
    const warehouseLabel = pdfWarehouseInfo.warehouseName
      ? pdfWarehouseInfo.warehouseName + " — "
      : "";
    const footerY = pageHeight - 22;
    const pageLimit = footerY - 8;
    const cargoSummary = {
      distinctItems: this.cargoItems.length,
      totalUnits: this.cargoItems.reduce((sum, item) => sum + item.quantity, 0),
      boxLines: this.cargoItems.filter((item) => item.packageType === "box")
        .length,
      boxUnits: this.cargoItems.reduce(
        (sum, item) => sum + (item.packageType === "box" ? item.quantity : 0),
        0,
      ),
      palletLines: this.cargoItems.filter(
        (item) => item.packageType === "pallet",
      ).length,
      palletUnits: this.cargoItems.reduce(
        (sum, item) =>
          sum + (item.packageType === "pallet" ? item.quantity : 0),
        0,
      ),
      wrappedPallets: this.cargoItems.reduce(
        (sum, item) =>
          sum +
          (item.packageType === "pallet" && item.blackWrapping
            ? item.quantity
            : 0),
        0,
      ),
    };

    const drawFooter = () => {
      doc.setDrawColor(...lightGray);
      doc.line(20, footerY, 190, footerY);

      doc.setFont("helvetica", "normal");
      doc.setFontSize(8);
      doc.setTextColor(...grayColor);
      doc.text(
        warehouseLabel +
          pdfWarehouseInfo.address +
          ", " +
          pdfWarehouseInfo.city,
        105,
        footerY + 7,
        { align: "center" },
      );
      doc.text(
        `${pdfWarehouseInfo.phone}  |  ${pdfWarehouseInfo.email}  |  ${pdfWarehouseInfo.website}`,
        105,
        footerY + 13,
        { align: "center" },
      );
    };

    const startNewPage = () => {
      drawFooter();
      doc.addPage();
    };

    // ===== HEADER - DRAMATIC GRADIENT BAR =====
    // Dark gradient background
    doc.setFillColor(...darkNavy);
    doc.rect(0, 0, 210, 55, "F");

    // Accent stripe
    doc.setFillColor(...accentColor);
    doc.rect(0, 55, 210, 3, "F");

    // Add company logo (embedded base64) - maintains portrait aspect ratio (784x1168 = ~2:3)
    // Logo dimensions: 28mm wide x 42mm tall to match original proportions
    try {
      doc.addImage(COMPANY_LOGO_BASE64, "JPEG", 10, 6, 28, 42);
    } catch (e) {
      console.log("Logo could not be added:", e);
    }

    // Company name - large and bold (positioned after logo)
    doc.setFont("helvetica", "bold");
    doc.setFontSize(28);
    doc.setTextColor(255, 255, 255);
    doc.text("MIAMI ALLIANCE", 44, 25);

    // 3PL in accent color
    doc.setTextColor(...accentColor);
    doc.text("3PL", 44, 40);

    // Tagline
    doc.setFont("helvetica", "normal");
    doc.setFontSize(11);
    doc.setTextColor(148, 163, 184);
    doc.text("WAREHOUSING  |  FULFILLMENT  |  LOGISTICS", 44, 50);

    // Quote badge on right
    doc.setFillColor(...accentColor);
    doc.roundedRect(145, 10, 55, 35, 3, 3, "F");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.setTextColor(255, 255, 255);
    doc.text("INSTANT", 172, 22, { align: "center" });
    doc.setFontSize(16);
    doc.text("QUOTE", 172, 35, { align: "center" });

    // ===== QUOTE INFO BAR =====
    doc.setFillColor(...lightGray);
    doc.rect(0, 58, 210, 20, "F");

    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.setTextColor(...primaryColor);
    doc.text(`QUOTE #: ${quoteNumber}`, 20, 70);

    doc.setFont("helvetica", "normal");
    doc.setTextColor(...grayColor);
    doc.text(`Date: ${currentDate}`, 105, 70, { align: "center" });
    doc.text("Valid for 30 days", 190, 70, { align: "right" });

    // ===== PACKAGE DETAILS - LEFT COLUMN =====
    let yPos = 90;
    const leftCol = 20;
    const rightCol = 110;

    // Section header with icon
    doc.setFillColor(...primaryColor);
    doc.roundedRect(leftCol, yPos - 6, 80, 10, 2, 2, "F");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.setTextColor(255, 255, 255);
    doc.text("PACKAGE DETAILS", leftCol + 5, yPos + 1);

    yPos += 12;

    // Package info with styled rows - multi-item support
    const packageDetails = [];
    if (this.cargoItems.length > 1) {
      packageDetails.push(
        ["Distinct Items", `${cargoSummary.distinctItems}`],
        ["Total Units", `${cargoSummary.totalUnits}`],
      );
      if (cargoSummary.boxLines > 0) {
        packageDetails.push([
          "Box Lines",
          `${cargoSummary.boxLines} (${cargoSummary.boxUnits} units)`,
        ]);
      }
      if (cargoSummary.palletLines > 0) {
        packageDetails.push([
          "Pallet Lines",
          `${cargoSummary.palletLines} (${cargoSummary.palletUnits} units)`,
        ]);
      }
      if (cargoSummary.wrappedPallets > 0) {
        packageDetails.push([
          "Wrapped Pallets",
          `${cargoSummary.wrappedPallets}`,
        ]);
      }
      packageDetails.push(["Zone", this.getZoneName(this.shippingZone)]);
      packageDetails.push(["Details", "See itemized cargo pages"]);
    } else {
      packageDetails.push(
        ["Type", this.packageType === "pallet" ? "PALLET" : "BOX"],
        [
          "Dimensions",
          `${this.dimensions.length}" x ${this.dimensions.width}" x ${this.dimensions.height}"`,
        ],
        ["Weight", `${this.weight} lbs (actual)`],
        ["DIM Weight", `${dimWeight.toFixed(1)} lbs`],
        ["Billable", `${billableWeight.toFixed(1)} lbs`],
        ["Volume", `${cubicFt.toFixed(2)} cu ft`],
        ["Quantity", `${this.quantity} unit${this.quantity > 1 ? "s" : ""}`],
        ["Zone", this.getZoneName(this.shippingZone)],
      );
    }

    doc.setFontSize(9);
    // Limit package details to avoid overflow — show max 12 items, summarize rest
    const maxPkgRows = 12;
    const pkgToShow = packageDetails.slice(0, maxPkgRows);
    const pkgOverflow = packageDetails.length - maxPkgRows;
    if (pkgOverflow > 0) {
      pkgToShow.push([`+ ${pkgOverflow} more items`, "see breakdown"]);
    }
    pkgToShow.forEach(([label, value], index) => {
      const rowY = yPos + index * 7;
      if (index % 2 === 0) {
        doc.setFillColor(248, 250, 252);
        doc.rect(leftCol, rowY - 4, 80, 7, "F");
      }
      doc.setFont("helvetica", "normal");
      doc.setTextColor(...grayColor);
      doc.text(label + ":", leftCol + 3, rowY);
      doc.setFont("helvetica", "bold");
      doc.setTextColor(...primaryColor);
      // Truncate long values to prevent horizontal overflow
      const truncVal = value.length > 30 ? value.substring(0, 28) + "…" : value;
      doc.text(truncVal, leftCol + 77, rowY, { align: "right" });
    });
    const leftColBottom = yPos + pkgToShow.length * 7;

    // ===== PRICING BREAKDOWN - RIGHT COLUMN =====
    yPos = 90;

    // Section header
    doc.setFillColor(...accentColor);
    doc.roundedRect(rightCol, yPos - 6, 80, 10, 2, 2, "F");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.setTextColor(255, 255, 255);
    doc.text("PRICING BREAKDOWN", rightCol + 5, yPos + 1);

    yPos += 12;

    // Pricing rows
    const priceRows = [
      [
        "Storage (" + this.storageDays + "d)",
        this.formatCurrency(results.storage),
      ],
      ["Handling Fee", this.formatCurrency(results.handling)],
      ["Pick & Pack", this.formatCurrency(results.pickPack)],
    ];
    // Add shipping or dropship or nothing
    if (this.shippingZone === "none") {
      priceRows.push(["Shipping", "N/A"]);
    } else if (this.shippingZone === "dropship") {
      // Add each dropship line item
      const breakdown = this.getDropShipBreakdown();
      if (breakdown.length > 0) {
        breakdown.forEach((item) => {
          priceRows.push([
            `${item.label} x${item.qty}`,
            this.formatCurrency(item.total),
          ]);
        });
      } else {
        priceRows.push(["Drop Ship", "$0.00"]);
      }
    } else if (this.shippingZone === "localDelivery") {
      priceRows.push([
        "Local Delivery (Flat)",
        this.formatCurrency(results.shipping),
      ]);
    } else if (this.shippingZone === "pickup") {
      priceRows.push([
        "Warehouse Pick Up (Flat)",
        this.formatCurrency(results.shipping),
      ]);
    } else {
      priceRows.push(["Est. Shipping", this.formatCurrency(results.shipping)]);
    }
    // Add black wrapping if any item has it selected
    const anyWrappingPdf = this.cargoItems.some(
      (item) => item.packageType === "pallet" && item.blackWrapping,
    );
    if (anyWrappingPdf && results.wrapping > 0) {
      priceRows.push(["Black Wrapping", this.formatCurrency(results.wrapping)]);
    }

    // Add FBA Prep line items if enabled
    if (this.fbaPrep && this.fbaPrep.enabled) {
      const fbaBreakdown = this.getFbaPrepBreakdown();
      if (fbaBreakdown.length > 0) {
        fbaBreakdown.forEach((item) => {
          priceRows.push([
            `FBA: ${item.label} x${item.qty}`,
            this.formatCurrency(item.total),
          ]);
        });
      }
    }

    // Limit pricing rows to max 15 to prevent overflow — summarize extras
    const maxPriceRows = 15;
    let priceRowsToShow = priceRows;
    let priceOverflowCount = 0;
    if (priceRows.length > maxPriceRows) {
      priceRowsToShow = priceRows.slice(0, maxPriceRows - 1);
      priceOverflowCount = priceRows.length - (maxPriceRows - 1);
      // Sum the overflow items
      const overflowTotal = priceRows
        .slice(maxPriceRows - 1)
        .reduce((sum, row) => {
          const val = parseFloat(row[1].replace(/[^0-9.-]/g, "")) || 0;
          return sum + val;
        }, 0);
      priceRowsToShow.push([
        `+ ${priceOverflowCount} more items`,
        this.formatCurrency(overflowTotal),
      ]);
    }

    doc.setFontSize(10);
    priceRowsToShow.forEach(([service, amount], index) => {
      const rowY = yPos + index * 9;
      if (index % 2 === 0) {
        doc.setFillColor(248, 250, 252);
        doc.rect(rightCol, rowY - 4, 80, 9, "F");
      }
      doc.setFont("helvetica", "normal");
      doc.setTextColor(...grayColor);
      // Truncate long service names
      const truncService =
        service.length > 28 ? service.substring(0, 26) + "…" : service;
      doc.text(truncService, rightCol + 3, rowY + 1);
      doc.setFont("helvetica", "bold");
      doc.setTextColor(...primaryColor);
      doc.text(amount, rightCol + 77, rowY + 1, { align: "right" });
    });
    const rightColBottom = yPos + priceRowsToShow.length * 9;

    // TOTAL - Big and bold — positioned dynamically after pricing rows
    const totalY = rightColBottom + 8;
    doc.setFillColor(...primaryColor);
    doc.roundedRect(rightCol, totalY - 6, 80, 16, 2, 2, "F");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.setTextColor(255, 255, 255);
    doc.text("TOTAL", rightCol + 5, totalY + 3);
    doc.setFontSize(16);
    doc.setTextColor(...accentColor);
    doc.text(this.formatCurrency(results.total), rightCol + 75, totalY + 4, {
      align: "right",
    });

    // ===== RATE DETAILS — dynamic Y based on tallest column =====
    const totalBoxBottom = totalY + 12;
    yPos = Math.max(leftColBottom, totalBoxBottom) + 10;

    // Check if we need a new page before the detail sections begin
    if (yPos > pageLimit) {
      startNewPage();
      yPos = pageStartY;
    }

    doc.setDrawColor(...lightGray);
    doc.setLineWidth(0.5);
    doc.line(20, yPos, 190, yPos);

    yPos += 10;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.setTextColor(...primaryColor);
    doc.text("RATE DETAILS", 20, yPos);

    yPos += 8;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.setTextColor(...grayColor);

    const hasPallet = this.cargoItems.some(
      (item) => item.packageType === "pallet",
    );
    const hasBox = this.cargoItems.some((item) => item.packageType === "box");
    const rates = [];
    if (hasBox) {
      rates.push("Box: $0.025/cu ft/day | $3.50 handling | $1.25 P&P");
    }
    if (hasPallet) {
      rates.push("Pallet: $0.75/day | $15.00 handling | $5.00 P&P");
    }
    if (this.shippingZone === "none") {
      rates.push("Shipping: N/A");
    } else if (this.shippingZone === "dropship") {
      rates.push("Drop Ship: Env $1.50 | Sm $3.00 | Med $5.00 | Lg $20.00");
    } else if (this.shippingZone === "localDelivery") {
      rates.push(
        `Local Delivery: $${(PRICING.localDeliveryBase || 120).toFixed(2)} base + $${(PRICING.localDeliveryPerUnit || 30).toFixed(2)}/extra pallet`,
      );
    } else if (this.shippingZone === "pickup") {
      rates.push(
        `Warehouse Pick Up: $${(PRICING.pickupBase || 120).toFixed(2)} base + $${(PRICING.pickupPerUnit || 30).toFixed(2)}/extra pallet`,
      );
    } else {
      rates.push(
        `Shipping: $${PRICING.shippingZones[this.shippingZone].toFixed(2)}/lb (${this.getZoneName(this.shippingZone)})`,
      );
    }
    if (hasPallet) {
      rates.push(`Black Wrap: $${PRICING.blackWrapping.toFixed(2)}/pallet`);
    }
    const rateLines = doc.splitTextToSize(rates.join("   |   "), 170);
    doc.text(rateLines, 105, yPos, { align: "center" });
    yPos += rateLines.length * 4;

    // FBA Prep rate details (separate line if enabled)
    if (this.fbaPrep && this.fbaPrep.enabled) {
      const fbaBreakdown = this.getFbaPrepBreakdown();
      if (fbaBreakdown.length > 0) {
        yPos += 4;
        const fbaRateStr = fbaBreakdown
          .map((item) => `${item.label}: $${item.rate.toFixed(2)}/${item.unit}`)
          .join("   |   ");
        const fbaRateLines = doc.splitTextToSize(
          "FBA Prep: " + fbaRateStr,
          170,
        );
        doc.text(fbaRateLines, 105, yPos, { align: "center" });
        yPos += fbaRateLines.length * 4;
      }
    }

    // ===== IMPORTANT NOTES — dynamic Y =====
    yPos += 10;

    // Check if notes section needs a new page
    if (yPos + 35 > pageLimit) {
      startNewPage();
      yPos = pageStartY;
    }

    doc.setFillColor(254, 249, 195); // Yellow background
    doc.roundedRect(20, yPos - 5, 170, 35, 3, 3, "F");
    doc.setDrawColor(250, 204, 21);
    doc.setLineWidth(0.5);
    doc.roundedRect(20, yPos - 5, 170, 35, 3, 3, "S");

    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(146, 64, 14);
    doc.text("IMPORTANT NOTES", 25, yPos + 3);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(7);
    const notes = [
      "This is an estimate. Final pricing may vary based on actual dimensions and services.",
      "Volume discounts available for recurring shipments. Quote valid for 30 days.",
      "Special handling, hazmat, or oversized items may incur additional fees.",
    ];
    notes.forEach((note, i) => {
      doc.text("• " + note, 25, yPos + 11 + i * 6);
    });

    // ===== CALL TO ACTION — dynamic Y =====
    yPos += 40;

    // Check if CTA needs a new page
    if (yPos + 25 > pageLimit) {
      startNewPage();
      yPos = pageStartY;
    }

    doc.setFillColor(...primaryColor);
    doc.roundedRect(20, yPos, 170, 25, 3, 3, "F");

    doc.setFont("helvetica", "bold");
    doc.setFontSize(14);
    doc.setTextColor(255, 255, 255);
    doc.text("Ready to get started?", 30, yPos + 11);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text(
      "Contact us for a detailed quote tailored to your needs.",
      30,
      yPos + 20,
    );

    // Contact button style
    doc.setFillColor(...accentColor);
    doc.roundedRect(145, yPos + 5, 40, 15, 2, 2, "F");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.text("CONTACT", 165, yPos + 15, { align: "center" });
    doc.link(145, yPos + 5, 40, 15, {
      url: "https://miamialliance3pl.com/contact.html",
    });

    if (cargoSummary.distinctItems > 1) {
      const itemizedResults =
        multiResult && Array.isArray(multiResult.items)
          ? multiResult.items
          : [];
      let itemY = pageStartY;

      const beginItemizedPage = (continued = false) => {
        itemY = pageStartY;
        doc.setFillColor(...primaryColor);
        doc.roundedRect(20, itemY - 6, 170, 10, 2, 2, "F");
        doc.setFont("helvetica", "bold");
        doc.setFontSize(11);
        doc.setTextColor(255, 255, 255);
        doc.text(
          continued ? "ITEMIZED CARGO (CONT.)" : "ITEMIZED CARGO",
          25,
          itemY + 1,
        );

        itemY += 14;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(9);
        doc.setTextColor(...grayColor);
        doc.text(
          `${cargoSummary.distinctItems} distinct items  |  ${cargoSummary.totalUnits} total units`,
          20,
          itemY,
        );
        itemY += 8;
      };

      startNewPage();
      beginItemizedPage(false);

      this.cargoItems.forEach((item, idx) => {
        const itemResult = itemizedResults[idx] || null;
        const typeLabel = item.packageType === "pallet" ? "Pallet" : "Box";
        const dims = `${item.dimensions.length}"x${item.dimensions.width}"x${item.dimensions.height}"`;
        const itemTotal = itemResult
          ? itemResult.storage +
            itemResult.handling +
            itemResult.pickPack +
            itemResult.shipping +
            itemResult.wrapping
          : null;
        const detailParts = [
          `${typeLabel} ${dims}`,
          `${item.weight}lbs x${item.quantity}`,
        ];

        if (itemResult) {
          detailParts.push(
            `Storage ${this.formatCurrency(itemResult.storage)}`,
            `Handling ${this.formatCurrency(itemResult.handling)}`,
            `P&P ${this.formatCurrency(itemResult.pickPack)}`,
          );
          if (itemResult.shipping > 0) {
            detailParts.push(
              `Ship ${this.formatCurrency(itemResult.shipping)}`,
            );
          }
          if (itemResult.wrapping > 0) {
            detailParts.push(
              `Wrap ${this.formatCurrency(itemResult.wrapping)}`,
            );
          }
        }

        const detailLines = doc.splitTextToSize(
          detailParts.join("   |   "),
          160,
        );
        const rowHeight = 12 + detailLines.length * 4;

        if (itemY + rowHeight > pageLimit) {
          startNewPage();
          beginItemizedPage(true);
        }

        if (idx % 2 === 0) {
          doc.setFillColor(248, 250, 252);
          doc.roundedRect(20, itemY - 5, 170, rowHeight, 2, 2, "F");
        }

        doc.setFont("helvetica", "bold");
        doc.setFontSize(10);
        doc.setTextColor(...primaryColor);
        doc.text(`Item #${idx + 1}`, 24, itemY + 1);
        doc.text(
          itemTotal === null
            ? "Included in total"
            : this.formatCurrency(itemTotal),
          186,
          itemY + 1,
          { align: "right" },
        );

        doc.setFont("helvetica", "normal");
        doc.setFontSize(8);
        doc.setTextColor(...grayColor);
        doc.text(detailLines, 24, itemY + 8);

        itemY += rowHeight + 4;
      });
    }

    // ===== FOOTER — always at bottom of current page =====
    drawFooter();

    // Track PDF download
    if (window.MA3PLAnalytics) {
      MA3PLAnalytics.trackPDFDownload(quoteNumber, results.total);
    }

    // Save PDF
    doc.save(`MiamiAlliance3PL_Quote_${quoteNumber}.pdf`);

    // Show success message
    this.showPDFSuccess(quoteNumber);
  }

  showPDFSuccess(quoteNumber) {
    // Create success toast
    const toast = document.createElement("div");
    toast.className = "pdf-toast";
    toast.innerHTML = `
            <div class="pdf-toast-icon">✓</div>
            <div class="pdf-toast-content">
                <strong>Quote Downloaded!</strong>
                <span>${quoteNumber}</span>
            </div>
        `;
    document.body.appendChild(toast);

    // Animate in
    setTimeout(() => toast.classList.add("show"), 100);

    // Remove after 4 seconds
    setTimeout(() => {
      toast.classList.remove("show");
      setTimeout(() => toast.remove(), 500);
    }, 4000);
  }
}

// Initialize when DOM is ready
document.addEventListener("DOMContentLoaded", () => {
  window.quoteCalculator = new QuoteCalculator();

  // Add PDF button event listener
  const pdfBtn = document.getElementById("download-pdf-btn");
  if (pdfBtn) {
    pdfBtn.addEventListener("click", () => {
      window.quoteCalculator.generatePDF();
    });
  }
});
